result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/bench.py", "content": """"Auto-calibrating micro-benchmark harness (timeit-style).

The harness picks the number of loops ``n`` automatically: start at 1,
grow by 10x until a single batch of ``n`` calls takes >= 50 ms, then
time 7 batches at that ``n`` and report per-call p50/p99.

The timer is injectable: any zero-argument callable returning seconds.
"""

from __future__ import annotations

import time
from dataclasses import dataclass
from typing import Callable


Timer = Callable[[], float]


def measure_batch(fn: Callable[[], object], n: int, timer: Timer) -> float:
    """Run ``fn`` ``n`` times; return elapsed seconds via ``timer``."""
    t0 = timer()
    for _ in range(n):
        fn()
    t1 = timer()
    return t1 - t0


def calibrate(
    fn: Callable[[], object],
    timer: Timer = time.perf_counter,
    target_ms: float = 50.0,
) -> int:
    """Find loops-per-batch ``n``: 1, 10, 100, ... until a batch >= target_ms."""
    n = 1
    while True:
        elapsed_s = measure_batch(fn, n, timer)
        if elapsed_s * 1000.0 >= target_ms:
            return n
        n *= 10


def percentile(sorted_values: list[float], q: float) -> float:
    """Nearest-rank percentile of an already-sorted list."""
    if not sorted_values:
        raise ValueError("empty sample")
    idx = min(len(sorted_values) - 1, int(q * (len(sorted_values) - 1) + 0.5))
    return sorted_values[idx]


@dataclass
class BenchResult:
    name: str
    loops_per_batch: int
    batches: int
    p50: float  # seconds per call
    p99: float  # seconds per call

    @property
    def p50_ms(self) -> float:
        return self.p50 * 1000.0

    @property
    def p99_ms(self) -> float:
        return self.p99 * 1000.0


def bench(
    fn: Callable[[], object],
    name: str = "bench",
    timer: Timer = time.perf_counter,
    target_ms: float = 50.0,
    batches: int = 7,
) -> BenchResult:
    """Calibrate, then time ``batches`` batches; report per-call p50/p99."""
    n = calibrate(fn, timer, target_ms)
    per_call: list[float] = []
    for _ in range(batches):
        per_call.append(measure_batch(fn, n, timer) / n)
    per_call.sort()
    return BenchResult(
        name=name,
        loops_per_batch=n,
        batches=batches,
        p50=percentile(per_call, 0.50),
        p99=percentile(per_call, 0.99),
    )
