from __future__ import annotations

Mat2 = tuple[int, int, int, int]  # (a, b, c, d) representing [[a, b], [c, d]]


def fib_iterative(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def _mat_mul(x: Mat2, y: Mat2) -> Mat2:
    a, b, c, d = x
    e, f, g, h = y
    return (a * e + b * g, a * f + b * h, c * e + d * g, c * f + d * h)


def _mat_pow(m: Mat2, p: int) -> Mat2:
    result: Mat2 = (1, 0, 0, 1)  # identity
    base = m
    while p:
        if p & 1:
            result = _mat_mul(result, base)
        base = _mat_mul(base, base)
        p >>= 1
    return result


def fib_matrix(n: int) -> int:
    """F(n) via [[1,1],[1,0]]^n; F(n) ends up in the off-diagonal [0][1]."""
    if n == 0:
        return 0
    a, b, _c, _d = _mat_pow((1, 1, 1, 0), n)
    return b


def verify_agreement(limit: int = 400) -> None:
    for k in range(limit + 1):
        assert fib_iterative(k) == fib_matrix(k), f"mismatch at fib({k})"


if __name__ == "__main__":
    verify_agreement()
    print("iterative(400) == matrix(400):", fib_iterative(400) == fib_matrix(400))
